class Solution:
    def countSpecialSubsequences(self, nums: List[int]) -> int:
        MOD = 10 ** 9 + 7
        n = len(nums)
        dp = [[0] * 3 for _ in range(n + 1)]
        for i in range(n):
            dp[i + 1] = dp[i][:]
            if nums[i] == 0:
                dp[i + 1][0] = (dp[i][0] * 2 + 1) % MOD
            elif nums[i] == 1:
                dp[i + 1][1] = (dp[i][1] * 2 + dp[i][0]) % MOD
            else:
                dp[i + 1][2] = (dp[i][2] * 2 + dp[i][1]) % MOD
        return dp[n][2]

