class Solution {
public:
    int countSpecialSubsequences(vector<int>& nums) {
        const long long MOD = 1e9 + 7;
        int n = nums.size();
        vector<array<long long, 3>> dp(n + 1, {0, 0, 0});
        for (int i = 0; i < n; ++i) {
            dp[i + 1] = dp[i];
            if (nums[i] == 0) dp[i + 1][0] = (dp[i][0] * 2 + 1) % MOD;
            else if (nums[i] == 1) dp[i + 1][1] = (dp[i][1] * 2 + dp[i][0]) % MOD;
            else dp[i + 1][2] = (dp[i][2] * 2 + dp[i][1]) % MOD;
        }
        return dp[n][2];
    }
};

