class Solution {
    public int countSpecialSubsequences(int[] nums) {
        final long MOD = 1_000_000_007L;
        int n = nums.length;
        long[][] dp = new long[n + 1][3];
        for (int i = 0; i < n; ++i) {
            dp[i + 1] = dp[i].clone();
            if (nums[i] == 0) dp[i + 1][0] = (dp[i][0] * 2 + 1) % MOD;
            else if (nums[i] == 1) dp[i + 1][1] = (dp[i][1] * 2 + dp[i][0]) % MOD;
            else dp[i + 1][2] = (dp[i][2] * 2 + dp[i][1]) % MOD;
        }
        return (int) dp[n][2];
    }
}

