var countSpecialSubsequences = function(nums) {
    const MOD = 1e9 + 7;
    const n = nums.length;
    const dp = [[0, 0, 0]];
    for (let i = 0; i < n; i++) {
        const nxt = [...dp[i]];
        if (nums[i] === 0) nxt[0] = (dp[i][0] * 2 + 1) % MOD;
        else if (nums[i] === 1) nxt[1] = (dp[i][1] * 2 + dp[i][0]) % MOD;
        else nxt[2] = (dp[i][2] * 2 + dp[i][1]) % MOD;
        dp.push(nxt);
    }
    return dp[n][2];
};

